import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import Editor from '@monaco-editor/react';
import { Terminal } from 'xterm';
import 'xterm/css/xterm.css';
import '../css/Projectpage.css';

export default function ProjectPage() {
    const navigate = useNavigate();
    const [projectName, setProjectName] = useState('MyProject');
    const [files, setFiles] = useState([]);
    const [activeIndex, setActiveIndex] = useState(null);
    const termRef = useRef(null);
    const xtermRef = useRef(null);
    const editorRef = useRef(null);

    useEffect(() => {
        xtermRef.current = new Terminal({ convertEol: true });
        xtermRef.current.open(termRef.current);
        xtermRef.current.writeln('Ready.');
        const originalLog = console.log;
        console.log = (...args) => {
            xtermRef.current.writeln(args.join(' '));
            originalLog(...args);
        };
        return () => { console.log = originalLog; };
    }, []);

    const handleBack = () => navigate(-1);
    const handleRename = () => {
        const name = prompt('프로젝트 이름을 입력하세요:', projectName);
        if (name) setProjectName(name);
    };
    const handleNewFile = () => {
        const fileName = prompt('새 파일 이름을 입력하세요 (확장자 포함):');
        if (!fileName) return;
        if (files.some(f => f.name === fileName)) {
            alert('이미 동일한 이름의 파일이 존재합니다.');
            return;
        }
        setFiles(prev => {
            const next = [...prev, { name: fileName, content: '' }];
            setActiveIndex(next.length - 1);
            return next;
        });
    };
    const handleDeleteFile = idx => {
        if (window.confirm(`정말 '${files[idx].name}' 파일을 삭제하시겠습니까?`)) {
            setFiles(prev => prev.filter((_, i) => i !== idx));
            setActiveIndex(prev => (prev === idx ? null : prev > idx ? prev - 1 : prev));
        }
    };
    const handleFileDrop = e => {
        e.preventDefault();
        Array.from(e.dataTransfer.files).forEach(file => {
            const reader = new FileReader();
            reader.onload = () => {
                setFiles(prev => {
                    const next = [...prev, { name: file.name, content: reader.result }];
                    setActiveIndex(next.length - 1);
                    return next;
                });
            };
            reader.readAsText(file);
        });
    };
    const handleDragOver = e => e.preventDefault();
    const handleSelectFile = idx => setActiveIndex(idx);
    const handleEditorDidMount = editor => { editorRef.current = editor; };
    const runCode = () => {
        if (!editorRef.current) return;
        const code = editorRef.current.getValue();
        xtermRef.current.clear();
        try { eval(code); }
        catch (err) { xtermRef.current.writeln(err.toString()); }
    };

    return (
        <div className="ide-container replit-style">
            <header className="ide-header">
                <button onClick={handleBack} className="ide-back-btn">&larr;</button>
                <h1 className="project-name" onClick={handleRename}>{projectName}</h1>
                <button onClick={handleNewFile} className="new-file-btn">Run Editor</button>
            </header>
            <div className="ide-body">
                {/* Left: File Explorer */}
                <aside className="file-tree" onDrop={handleFileDrop} onDragOver={handleDragOver}>
                    {files.map((f, i) => (
                        <div key={i} className={`file-item ${activeIndex === i ? 'active' : ''}`}>
                            <span onClick={() => handleSelectFile(i)}>{f.name}</span>
                            <button className="delete-file" onClick={() => handleDeleteFile(i)}>×</button>
                        </div>
                    ))}
                    <div className="file-item placeholder">+ Create or drag file</div>
                </aside>
                {/* Main: Editor + Console */}
                <section className="main-pane">
                    <div className="editor-container">
                        {activeIndex !== null ? (
                            <Editor
                                height="100%"
                                language="javascript"
                                theme="vs-dark"
                                value={files[activeIndex].content}
                                onMount={handleEditorDidMount}
                                onChange={val => setFiles(prev => prev.map((f, j) => j === activeIndex ? { ...f, content: val || '' } : f))}
                            />
                        ) : (
                            <div className="no-file">파일을 선택하거나 생성하세요</div>
                        )}
                    </div>
                    <div className="console-container" ref={termRef} />
                    <button className="run-btn-floating" onClick={runCode}>▶ Run</button>
                </section>
            </div>
        </div>
    );
}
